/** Rewrites src/core2/data/outcome-web/coverage.json from the links and what the core can read. */
import { writeFileSync } from "node:fs";
import { coverageTable } from "../../src/core2/outcome-web-model";

const table = coverageTable();
writeFileSync(
  "src/core2/data/outcome-web/coverage.json",
  `${JSON.stringify(
    {
      about:
        "Every researched outcome-web link, wired or waiting on the named measures some engine must provide. Generated by scripts/outcome-web/write-coverage.ts; src/core2/outcome-web.test.ts fails if this list and the code disagree.",
      ...table,
    },
    null,
    2,
  )}\n`,
);
console.log(
  `wired ${table.wired.length}, waiting ${Object.keys(table.waiting).length}`,
);
